// Augmentasi tipe <style jsx global> styled-jsx untuk program web.\n// styled-jsx me-augmentasi @types/react yang terlihat dari root (18);\n// tanpa file ini prop `jsx`/`global` pada <style> tidak dikenali karena\n// d.ts augmentasi styled-jsx tidak otomatis masuk program TypeScript web.\nimport 'react';\n\ndeclare module 'react' {\n  interface StyleHTMLAttributes<T> {\n    jsx?: boolean;\n    global?: boolean;\n  }\n}\n